-- 0005: weekly memorization plan (Fath -> Ahzab, one Madani mushaf page per week) + per-learner tick-offs. Additive and idempotent.
CREATE TABLE IF NOT EXISTS hefz_plan_weeks (
 week_number INTEGER PRIMARY KEY, title TEXT NOT NULL, surah_key TEXT NOT NULL,
 mushaf_page INTEGER NOT NULL, mushaf_page2 INTEGER, start_date DATE, days JSONB NOT NULL
);
CREATE TABLE IF NOT EXISTS hefz_plan_progress (
 user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, week_number INTEGER NOT NULL REFERENCES hefz_plan_weeks(week_number) ON DELETE CASCADE,
 day_index INTEGER NOT NULL CHECK (day_index BETWEEN 0 AND 6), done_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY (user_id, week_number, day_index)
);
CREATE INDEX IF NOT EXISTS hefz_plan_progress_week_idx ON hefz_plan_progress(week_number, user_id);
